(** * Actual execution *)

Lemma cpu_rule_substep : forall r old u,
  In r (getRules thieleCore) -> eval_cpu_rule old r = Some u ->
  Substep thieleCore old u (Rle (Some (attrName r))) (M.empty _).
Proof.
  intros r old u Hin He. eapply SingleRule with (a := attrType r).
  - destruct r. exact Hin.
  - unfold eval_cpu_rule in He.
    destruct (eval_linear_action old (attrType r type)) as [[updates ret]|] eqn:Hr; [|discriminate].
    inversion He; subst updates.
    assert (ret = WO) by apply word0. subst ret.
    apply eval_linear_action_sound. exact Hr.
Qed.

Fixpoint chsh_labels (n : nat) : list LabelT :=
  match n with
  | O => nil
  | S m => normalization_label "chsh_lassert_fsm" :: chsh_labels m
  end.

Lemma chsh_iter_multistep : forall b n,
  (forall m, (m < n)%nat -> hw_chsh_phase (chsh_iter m b) <> natToWord 5 0) ->
  Multistep thieleCore (hwb_regs b) (hwb_regs (chsh_iter n b)) (chsh_labels n).
Proof.
  intros b n. induction n as [|n IH]; intro H.
  - constructor. reflexivity.
  - cbn [chsh_iter chsh_labels].
    destruct (chsh_rule_enabled (chsh_iter n b) (H n (Nat.lt_succ_diag_r n))) as [u [Hu Eu]].
    rewrite <- Eu. eapply normalization_step_extends_execution.
    + apply IH. intros m Hm. apply H. lia.
    + exact (cpu_rule_substep _ _ _ chsh_rule_in Hu).
Qed.

Lemma natToWord5_succ_ne0 : forall m, (m <= 22)%nat -> natToWord 5 (S m) <> natToWord 5 0.
Proof.
  intros m Hm.
  assert (Hc : m = 0%nat \/ m = 1%nat \/ m = 2%nat \/ m = 3%nat \/ m = 4%nat \/ m = 5%nat \/ m = 6%nat \/
    m = 7%nat \/ m = 8%nat \/ m = 9%nat \/ m = 10%nat \/ m = 11%nat \/ m = 12%nat \/ m = 13%nat \/
    m = 14%nat \/ m = 15%nat \/ m = 16%nat \/ m = 17%nat \/ m = 18%nat \/ m = 19%nat \/ m = 20%nat \/
    m = 21%nat \/ m = 22%nat) by lia.
  repeat destruct Hc as [Hc|Hc]; subst m; word_ne.
Qed.

(** One step-rule firing and the 23 CHSH FSM firings are an actual Kami
    execution from a live boundary. *)
Theorem chsh_lassert_execution : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB),
  step_fetched b = chsh_lassert_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false -> hw_live b ->
  Multistep thieleCore (hwb_regs b) (hwb_regs (chsh_iter 23 (step_next b)))
    (chsh_labels 23 ++ [normalization_label "step"]).
Proof.
  intros a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb Hlive.
  eapply normalization_multistep_trans; [exact (live_step_multistep b Hlive)|].
  apply chsh_iter_multistep. intros m Hm.
  destruct (chsh_run_result (step_next b) (step_chsh_lassert_chsh_phase a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb)) as [Hph _].
  rewrite (Hph m ltac:(lia)). apply natToWord5_succ_ne0. lia.
Qed.

(** While the CHSH FSM runs, it is the only rule that can fire. *)
Theorem chsh_only_rule_enabled : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB) m r,
  step_fetched b = chsh_lassert_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false -> (m <= 22)%nat ->
  In r (getRules thieleCore) ->
  eval_cpu_rule (hwb_regs (chsh_iter m (step_next b))) r <> None -> r = chsh_rule.
Proof.
  intros a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b m r Hf Hb Hm Hin Hr.
  destruct (chsh_run_result (step_next b) (step_chsh_lassert_chsh_phase a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb)) as [Hph _].
  pose proof (Hph m Hm) as Pm.
  pose proof (step_chsh_lassert_lassert_phase a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) as Lp.
  pose proof (step_chsh_lassert_mc_phase a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b Hf Hb) as Mp.
  rewrite <- (iter_keeps_lassert_phase m) in Lp. rewrite <- (iter_keeps_mc_phase m) in Mp.
  set (c := chsh_iter m (step_next b)) in *.
  rewrite cpu_rules_listed in Hin. apply in_map_iff in Hin. destruct Hin as [n [Hrn Hn]]. subst r.
  cbn [In] in Hn.
  repeat destruct Hn as [Hn|Hn]; try contradiction; subst n; try reflexivity; exfalso; apply Hr.
  - change (normalization_rule 0) with dispatch_rule. rewrite eval_cpu_rule_dispatch.
    apply step_rule_disabled. unfold step_guards. rewrite Pm.
    destruct (weq (natToWord 5 (S m)) (natToWord 5 0)) as [E|_];
      [exfalso; exact (natToWord5_succ_ne0 m Hm E)|].
    rewrite !andb_false_r. reflexivity.
  - apply lassert_fsm_header_disabled. rewrite Lp. word_ne.
  - apply lassert_fsm_scan_disabled. rewrite Lp. word_ne.
  - apply mc_morph_header_disabled. rewrite Mp. word_ne.
  - apply mc_morph_loop_disabled. rewrite Mp. word_ne.
  - apply mc_copy_loop_disabled. rewrite Mp. word_ne.
  - apply mc_join_loop_disabled. rewrite Mp. word_ne.
  - apply mc_normalize_start_disabled. rewrite Mp. word_ne.
  - apply mc_normalize_scan_disabled. rewrite Mp. word_ne.
  - apply mc_normalize_emit_disabled. rewrite Mp. word_ne.
  - apply mc_commit_disabled. rewrite Mp. word_ne.
Qed.
